"""The rcfile the remote shell starts with."""

import shlex

from .items import Kind, selected_of_kind

LOGIN_SECTION = """\
# Generated by ssh-tote; recreated on every connection.
# Behave like a login shell first, so the server's own setup still applies.
[ -f /etc/profile ] && . /etc/profile
if [ -n "$BASH_VERSION" ]; then
  for __ssh_tote_f in "$HOME/.bash_profile" "$HOME/.bash_login" "$HOME/.profile"; do
    if [ -f "$__ssh_tote_f" ]; then . "$__ssh_tote_f"; break; fi
  done
  unset __ssh_tote_f
elif [ -f "$HOME/.profile" ]; then
  . "$HOME/.profile"
fi
"""

DOTFILES_SECTION = """\
# Dotfiles dir from --dir or the dir setting (same $SSHHOME layout as sshrc).
export SSHHOME="$SSH_TOTE_HOME/dir"
PATH="$SSHHOME/bin:$PATH"
if [ -n "$BASH_VERSION" ] && [ -f "$SSHHOME/.bashrc" ]; then
  . "$SSHHOME/.bashrc"
fi
"""

REMOTE_HOME = '"$HOME"'


def environment_section(items, local_home):
    lines = [
        f"export {item.name}={quote_with_remote_home(item.value, local_home)}"
        for item in selected_of_kind(items, Kind.ENV)
    ]
    return _section("Environment from your local shell", lines)


def alias_section(items):
    # The name is quoted too: zsh allows almost anything in one, even `;`.
    lines = [
        f"alias {shlex.quote(item.name + '=' + item.value)}"
        for item in selected_of_kind(items, Kind.ALIAS)
    ]
    return _section("Aliases from your local shell", lines)


def command_section(command):
    return f"eval {shlex.quote(command)}\nexit $?\n"


def join_sections(sections):
    return "\n".join(section for section in sections if section)


def _section(title, lines):
    if not lines:
        return ""
    return "\n".join([f"# {title}", *lines]) + "\n"


def quote_with_remote_home(value, local_home):
    """Quote value for sh, pointing paths under local_home at the remote $HOME.

    Colon-separated lists (PATH-like values) are handled piece by piece.
    """
    is_meaningful_home = local_home not in ("", "/")
    if is_meaningful_home and local_home in value:
        parts = value.split(":")
        return ":".join(_quote_path(part, local_home) for part in parts)
    return shlex.quote(value)


def _quote_path(path, local_home):
    if path == local_home:
        return REMOTE_HOME
    if path.startswith(local_home + "/"):
        return REMOTE_HOME + shlex.quote(path[len(local_home) :])
    return shlex.quote(path)
